DROP TABLE IF EXISTS `airports`;
CREATE TABLE `airports` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `iata_code` varchar(10) NOT NULL,
  `icao_code` varchar(10) DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `city` varchar(255) DEFAULT NULL,
  `province` varchar(100) DEFAULT NULL,
  `region` varchar(50) DEFAULT NULL,
  `country` varchar(255) DEFAULT NULL,
  `airport_type` varchar(50) NOT NULL DEFAULT 'domestic',
  `management_type` varchar(100) NOT NULL DEFAULT 'PT. Angkasa Pura Indonesia',
  `management_name` varchar(255) DEFAULT NULL,
  `usage_type` varchar(50) DEFAULT 'Komersial',
  `classification` varchar(50) DEFAULT NULL,
  `is_international` tinyint(1) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `data_incomplete` tinyint(1) NOT NULL DEFAULT 0,
  `source` varchar(100) NOT NULL DEFAULT 'PROJECT_REFERENCE',
  `source_url` varchar(500) DEFAULT NULL,
  `source_checked_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `airports_iata_code_unique` (`iata_code`),
  KEY `airports_icao_code_index` (`icao_code`)
) ENGINE=InnoDB AUTO_INCREMENT=92 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `airlines`;
CREATE TABLE `airlines` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `airline_code` varchar(10) NOT NULL,
  `airline_name` varchar(255) NOT NULL,
  `organization_code` varchar(50) DEFAULT NULL,
  `category` varchar(50) NOT NULL DEFAULT 'domestic',
  `country` varchar(100) NOT NULL DEFAULT 'Indonesia',
  `status` varchar(50) NOT NULL DEFAULT 'active',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `source` varchar(100) NOT NULL DEFAULT 'PROJECT_REFERENCE',
  `source_url` varchar(500) DEFAULT NULL,
  `source_checked_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `airlines_airline_code_unique` (`airline_code`),
  KEY `airlines_organization_code_index` (`organization_code`)
) ENGINE=InnoDB AUTO_INCREMENT=72 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `uploads`;
CREATE TABLE `uploads` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `original_filename` varchar(255) NOT NULL,
  `stored_path` varchar(255) NOT NULL,
  `season` varchar(20) NOT NULL DEFAULT 'summer',
  `airport_id` bigint(20) unsigned DEFAULT NULL,
  `total_rows` int(10) unsigned NOT NULL DEFAULT 0,
  `valid_rows` int(10) unsigned NOT NULL DEFAULT 0,
  `invalid_rows` int(10) unsigned NOT NULL DEFAULT 0,
  `duplicate_rows` int(10) unsigned NOT NULL DEFAULT 0,
  `parsing_confidence` decimal(5,2) NOT NULL DEFAULT 100.00,
  `validation_summary` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`validation_summary`)),
  `status` varchar(255) NOT NULL DEFAULT 'pending',
  `error_message` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `uploads_airport_id_foreign` (`airport_id`),
  CONSTRAINT `uploads_airport_id_foreign` FOREIGN KEY (`airport_id`) REFERENCES `airports` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `flights`;
CREATE TABLE `flights` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `upload_id` bigint(20) unsigned NOT NULL,
  `flight_number` varchar(20) NOT NULL,
  `airline_code` varchar(10) DEFAULT NULL,
  `aircraft_type` varchar(30) DEFAULT NULL,
  `origin` varchar(60) DEFAULT NULL,
  `destination` varchar(60) DEFAULT NULL,
  `scheduled_time` time NOT NULL,
  `operating_days` varchar(7) DEFAULT NULL,
  `flight_type` varchar(50) NOT NULL,
  `direction` varchar(20) NOT NULL DEFAULT 'arrival',
  `traffic_type` varchar(20) NOT NULL DEFAULT 'domestic',
  `parse_status` varchar(30) NOT NULL DEFAULT 'valid',
  `validation_status` varchar(30) NOT NULL DEFAULT 'valid',
  `validation_errors` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`validation_errors`)),
  `slot_status` enum('available','used') NOT NULL DEFAULT 'available',
  `paired_flight_id` bigint(20) unsigned DEFAULT NULL,
  `remarks` varchar(255) DEFAULT NULL,
  `raw_data` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_flights_upload_flnum` (`upload_id`,`flight_number`),
  KEY `idx_flights_upload_time` (`upload_id`,`scheduled_time`),
  KEY `idx_flights_upload_dir` (`upload_id`,`direction`),
  KEY `idx_flights_upload_traffic` (`upload_id`,`traffic_type`),
  KEY `idx_flights_upload_val` (`upload_id`,`validation_status`),
  CONSTRAINT `flights_upload_id_foreign` FOREIGN KEY (`upload_id`) REFERENCES `uploads` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5228 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `timeline_positions`;
CREATE TABLE `timeline_positions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `upload_id` bigint(20) unsigned NOT NULL,
  `flight_id` bigint(20) unsigned NOT NULL,
  `hour` tinyint(3) unsigned NOT NULL,
  `row` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `offset_minutes` smallint(5) unsigned NOT NULL DEFAULT 0,
  `color_hex` varchar(10) NOT NULL,
  `is_locked` tinyint(1) NOT NULL DEFAULT 0,
  `duration_minutes` smallint(5) unsigned NOT NULL DEFAULT 45,
  `section` varchar(20) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `timeline_positions_upload_id_flight_id_unique` (`upload_id`,`flight_id`),
  KEY `timeline_positions_flight_id_foreign` (`flight_id`),
  CONSTRAINT `timeline_positions_flight_id_foreign` FOREIGN KEY (`flight_id`) REFERENCES `flights` (`id`) ON DELETE CASCADE,
  CONSTRAINT `timeline_positions_upload_id_foreign` FOREIGN KEY (`upload_id`) REFERENCES `uploads` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5220 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `timeline_settings`;
CREATE TABLE `timeline_settings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `upload_id` bigint(20) unsigned NOT NULL,
  `ops_start` tinyint(3) unsigned NOT NULL DEFAULT 6,
  `ops_end` tinyint(3) unsigned NOT NULL DEFAULT 19,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `timeline_settings_upload_id_unique` (`upload_id`),
  CONSTRAINT `timeline_settings_upload_id_foreign` FOREIGN KEY (`upload_id`) REFERENCES `uploads` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `flight_pairings`;
CREATE TABLE `flight_pairings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `upload_id` bigint(20) unsigned NOT NULL,
  `arrival_flight_id` bigint(20) unsigned DEFAULT NULL,
  `departure_flight_id` bigint(20) unsigned DEFAULT NULL,
  `rotation_id` varchar(50) NOT NULL,
  `operating_day` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `rotation_status` varchar(30) NOT NULL DEFAULT 'PAIRED',
  `turnaround_minutes` smallint(5) unsigned DEFAULT NULL,
  `confidence` tinyint(3) unsigned NOT NULL DEFAULT 100,
  `remarks` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `flight_pairings_arrival_flight_id_foreign` (`arrival_flight_id`),
  KEY `flight_pairings_departure_flight_id_foreign` (`departure_flight_id`),
  KEY `flight_pairings_upload_id_operating_day_index` (`upload_id`,`operating_day`),
  KEY `flight_pairings_rotation_id_index` (`rotation_id`),
  CONSTRAINT `flight_pairings_arrival_flight_id_foreign` FOREIGN KEY (`arrival_flight_id`) REFERENCES `flights` (`id`) ON DELETE CASCADE,
  CONSTRAINT `flight_pairings_departure_flight_id_foreign` FOREIGN KEY (`departure_flight_id`) REFERENCES `flights` (`id`) ON DELETE CASCADE,
  CONSTRAINT `flight_pairings_upload_id_foreign` FOREIGN KEY (`upload_id`) REFERENCES `uploads` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `exports`;
CREATE TABLE `exports` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `upload_id` bigint(20) unsigned NOT NULL,
  `type` varchar(20) NOT NULL DEFAULT 'combined',
  `filename` varchar(255) NOT NULL,
  `disk` varchar(255) NOT NULL DEFAULT 'local',
  `path` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `exports_upload_id_foreign` (`upload_id`),
  CONSTRAINT `exports_upload_id_foreign` FOREIGN KEY (`upload_id`) REFERENCES `uploads` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


